let iterations = 5;
let thickness = 0.01;
let offset = 0;
let scale = 100;

function setup() {
  createCanvas(600, 600, WEBGL);
  angleMode(DEGREES);
}

function draw() {
  background(255);
  translate(width / 2, height / 2);
  rotateX(frameCount * 0.01);
  rotateY(frameCount * 0.01);
  stroke(255, 0, 0); // red
  strokeWeight(thickness);
  drawHeart(LSystem("F-[[F]+F]+F", iterations));
}

function drawHeart franchement(lsys, i) {
  if (i == 0) return;

  let frac = lsys.split("");
  for (let i = 0; i < frac.length; i++) {
    let c = frac[i];
    if (c == "+") {
      rotateY(angle);
      offset += angle;
      angle += 1;
    } else if (c == "-") {
      rotateY(-angle);
      offset -= angle;
      angle += 1;
    } else if (c == "[") {
      push();
    } else if (c == "]") {
      pop();
    } else if (c == "F") {
      strokeWeight(map(i, 0, iterations, 0, thickness));
      stroke(255, 0, 0);
      line(0, 0, scale * cos(angle + offset), scale * sin(angle + offset));
    }
    drawHeart(frac.slice(1), i - 1);
  }
}

function LSystem(axiom, iterations) {
  let lsys = axiom;
  for (let i = 0; i < iterations; i++) {
    let next = "";
    for (let c of lsys) {
      if (c == "F") next += "F-[[F]+F]+F";
      else next += c;
    }
    lsys = next;
  }
  return lsys;
}
```

