#include <stdio.h>
#include <stdlib.h>
#include <avr/io.h>
#include <avr/interrupt.h>
#include <avr/sleep.h>

#define LED_PIN 13 // Pin connected to the LED

int main() {
    // Set the LED pin as an output
    DDRB |= (1 << LED_PIN);

    // Set the LED pin low (off)
    PORTB |= (1 << LED_PIN);

    while (1) {
        // Blink the LED
        PORTB ^= (1 << LED_PIN);
        _delay_ms(500); // Delay for 500ms
    }
    return 0;
}
